import java.util.*;
public class Question_03{public static void main(String[]x){Map<String,List<String>>g=new LinkedHashMap<>();g.put("cart",List.of("pricing"));g.put("pricing",List.of("inventory"));g.put("inventory",List.of("payment"));g.put("payment",List.of());Map<String,Integer>d=new HashMap<>();for(String v:g.keySet())d.put(v,0);for(String v:g.keySet())for(String w:g.get(v))d.put(w,d.get(w)+1);Queue<String>q=new ArrayDeque<>();for(String v:g.keySet())if(d.get(v)==0)q.add(v);List<String>o=new ArrayList<>();while(!q.isEmpty()){String v=q.remove();o.add(v);for(String w:g.get(v)){d.put(w,d.get(w)-1);if(d.get(w)==0)q.add(w);}}System.out.println("Deployment order: "+o);System.out.println("Circular dependency: "+(o.size()!=g.size()));}}